use crate::{ana2, ana3, case::{Case2, Case3}, corpus, tally::Tally};
use serde_json::{Value, json};
#[test]
#[ignore]
fn selected() {
    let rows: Value = serde_json::from_str(&std::fs::read_to_string("../.nightly-triage/selected.json").unwrap()).unwrap();
    let mut output = Vec::new();
    for row in rows.as_array().unwrap() {
        let n = row["issue"].as_u64().unwrap();
        let value: Value = serde_json::from_str(&std::fs::read_to_string(format!("../.nightly-triage/model-{n}.json")).unwrap()).unwrap();
        let analysis = row["analysis"].as_str().unwrap();
        let relation = row["relation"].as_str().unwrap();
        let seed = row["seed"].as_u64().unwrap();
        let name = value["_nightly_name"].as_str().unwrap_or("replay");
        let t = Tally::default();
        match corpus::parse(&value.to_string()).unwrap() {
            corpus::Model::D2(s) => {
                let mut c = Case2::new(name, s);
                if let Some(d) = value.get("_nightly_dens") { c.dens = serde_json::from_value(d.clone()).unwrap(); }
                if n == 1965 {
                    use dedaliano_engine::metamorphic::{Rng, transform::Iso2};
                    let mut rng=Rng::new(seed ^ crate::checks2::hash(&c.name) ^ crate::checks2::hash(analysis));
                    let iso=Iso2::rotation(rng.range(0.1,6.2)).translated(rng.range(-50.0,50.0),rng.range(-50.0,50.0));
                    let _ = c.iso(&iso);
                    let q=Iso2::rotation(std::f64::consts::FRAC_PI_2*(1+rng.below(3)) as f64).translated(rng.range(-50.0,50.0),rng.range(-50.0,50.0));
                    let tc=c.iso(&q).unwrap();
                    std::fs::write("../.nightly-triage/rotated-1965.json",serde_json::to_vec_pretty(&tc.s).unwrap()).unwrap();
                    std::fs::write("../.nightly-triage/modal-base-1965.json",serde_json::to_vec_pretty(&dedaliano_engine::solver::modal::solve_modal_2d(&c.s,&c.dens,6)).unwrap()).unwrap();
                }
                let anas: Vec<_> = ana2::rows().into_iter().filter(|a| a.name == analysis).collect();
                assert_eq!(anas.len(), 1);
                if relation == "symmetry" {
                    for anti in [false, true] {
                        let sym = crate::symmetry::symmetrize_2d(&c.name, &c.s, anti).unwrap();
                        std::fs::write(format!("../.nightly-triage/sym-{n}-{anti}.json"), serde_json::to_vec_pretty(&sym.case.s).unwrap()).unwrap();
                        crate::symmetry::check_2d(&t, &sym, anti, &anas);
                    }
                } else {
                    let end = crate::INV_2D.iter().position(|r| *r == relation).unwrap()+1;
                    crate::checks2::check_case(&crate::checks2::Ctx { tally: &t, rng_seed: seed }, &c, &anas, &crate::INV_2D[..end]);
                }
            }
            corpus::Model::D3(s) => {
                let mut c = Case3::new(name, s);
                if let Some(d) = value.get("_nightly_dens") { c.dens = serde_json::from_value(d.clone()).unwrap(); }
                let anas: Vec<_> = ana3::rows().into_iter().filter(|a| a.name == analysis).collect();
                assert_eq!(anas.len(), 1);
                let end = crate::INV_3D.iter().position(|r| *r == relation).unwrap()+1;
                crate::checks3::check_case(&crate::checks3::Ctx { tally: &t, rng_seed: seed }, &c, &anas, &crate::INV_3D[..end]);
            }
        }
        println!("ISSUE {n} {}",t.report());
        output.push(json!({"issue":n,"result":t.replay_results(),"report":t.report()}));
    }
    std::fs::write("../.nightly-triage/replay-main.json",serde_json::to_vec_pretty(&output).unwrap()).unwrap();
}

