use dedaliano_engine::{types::*,solver::{assembly,dof::DofNumbering,constraints::FreeConstraintSystem,mass_matrix},linalg::*};
use serde_json::json;
fn main() {
 let value:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(".nightly-triage/model-1965.json").unwrap()).unwrap();
 let dens=serde_json::from_value(value["_nightly_dens"].clone()).unwrap();
 let mut out=vec![];
 for file in ["model-1965","rotated-1965"] {
  let s:SolverInput=serde_json::from_str(&std::fs::read_to_string(format!(".nightly-triage/{file}.json")).unwrap()).unwrap();
  let d=DofNumbering::build_2d(&s); let nf=d.n_free;let n=d.n_total;
  let asm=assembly::assemble_stiffness_2d(&s,&d);
  let mc=mass_matrix::assemble_mass_matrix_2d_sparse_inclined(&s,&d,&dens,&asm.inclined_transforms_2d);
  let mut m=vec![0.0;nf*nf];for j in 0..nf {let mut b=vec![0.0;nf];b[j]=1.0;let c=mc.sym_mat_vec(&b);for i in 0..nf{m[i*nf+j]=c[i];}}
  let free:Vec<_>=(0..nf).collect();let k=extract_submatrix(&asm.k,n,&free,&free);
  let cs=FreeConstraintSystem::build_2d(&s,&d).unwrap();
  let (k,m,ns)=if let Some(cs)=cs{(cs.reduce_matrix(&k),cs.reduce_matrix(&m),cs.n_free_indep)}else{(k,m,nf)};
  let r=dedaliano_engine::linalg::lanczos::lanczos_generalized_eigen(&k,&m,ns,6,0.0).unwrap();
  out.push(json!({"file":file,"n":ns,"K":k,"M":m,"values":r.values,"vectors":r.vectors}));
 }
 std::fs::write(".nightly-triage/modal-pencil.json",serde_json::to_vec_pretty(&out).unwrap()).unwrap();
}

