use dedaliano_engine::{types::*,solver::material_nonlinear,metamorphic::units::{Units,scale_2d}};
use serde_json::json;
fn main(){
 let s:SolverInput=serde_json::from_str(&std::fs::read_to_string(".nightly-triage/model-1977.json").unwrap()).unwrap();
 let mut all=vec![];
 for (l,f) in [(1.0,1.0),(1e-3,1e3),(25.0,1e-2),(0.3048,4.448)]{
  let u=Units::froude(l,f);let solver=scale_2d(&s,&u);let fy=250.0*u.stress();
  let input=NonlinearMaterialInput{solver:solver.clone(),material_models:solver.materials.values().map(|m|(m.id.to_string(),MaterialModel{model_type:"elastic_perfectly_plastic".into(),fy,alpha:None})).collect(),section_capacities:solver.sections.values().map(|x|{let h=(12.0*x.iz/x.a).sqrt();let b=x.a/h;(x.id.to_string(),SectionCapacity{np:fy*1000.0*x.a,mp:fy*1000.0*b*h*h/4.0,zp:None})}).collect(),max_iter:60,tolerance:1e-10,n_increments:4};
  let result=material_nonlinear::solve_nonlinear_material_2d(&input);
  all.push(json!({"l":l,"f":f,"input":input,"result":result}));
 }
 std::fs::write(".nightly-triage/material-1977.json",serde_json::to_vec_pretty(&all).unwrap()).unwrap();
}

