import fs from 'node:fs';
import * as e from '../web/src/lib/wasm/dedaliano_engine.js';
let rows=[];
for (const [n,fn] of [[1962,'solve_buckling_3d'],[1963,'solve_plastic_3d'],[1964,'certify_linear_3d'],[1966,'certify_linear_3d']]) {
 e.initSync({module:fs.readFileSync('web/src/lib/wasm/dedaliano_engine_bg.wasm')});
 let s=n===1966?fs.readFileSync('.nightly-triage/model-1966-decoded.json','utf8'):fs.readFileSync(`.nightly-triage/${n}.bin`).subarray(2).toString();
 try {
  const result=e[fn](n===1964||n===1966?JSON.parse(s):s,3);
  rows.push({issue:n,status:'returned',result:typeof result==='string'?JSON.parse(result):result});
 } catch(err) { rows.push({issue:n,status:err instanceof WebAssembly.RuntimeError?'WASM-TRAP':'refused',error:String(err)}); }
 console.log(n,rows.at(-1).status,rows.at(-1).error??'');
}
fs.writeFileSync('.nightly-triage/wasm.json',JSON.stringify(rows,null,2));

